--
-- Table structure for table `gl_book_subject_map`
--

DROP TABLE IF EXISTS `gl_book_subject_map`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gl_book_subject_map` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tenant_id` bigint NOT NULL DEFAULT '0' COMMENT '租户ID【多租户隔离字段】',
  `book_id` bigint NOT NULL COMMENT '账簿 gl_accounting_book.id',
  `standard_id` bigint NOT NULL COMMENT '准则 gl_standard.id',
  `local_subject_id` bigint NOT NULL COMMENT '本准则下的科目 md_subject.id',
  `local_subject_code` varchar(64) DEFAULT NULL COMMENT '科目编码(快照)',
  `local_subject_name` varchar(200) DEFAULT NULL COMMENT '科目名称(快照)',
  `common_subject_id` bigint DEFAULT NULL COMMENT '对应通用科目 md_subject.id(跨准则归一)',
  `mapping_type` varchar(16) NOT NULL DEFAULT 'DIRECT' COMMENT 'DIRECT直接对应/RECLASS重分类/NOT_APPLICABLE本准则不适用',
  `status` varchar(16) NOT NULL DEFAULT 'ENABLED' COMMENT 'ENABLED/DISABLED',
  `remark` varchar(500) DEFAULT NULL COMMENT '备注(差异原因)',
  `create_by` bigint DEFAULT NULL,
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP,
  `update_by` bigint DEFAULT NULL,
  `update_time` datetime DEFAULT NULL ON UPDATE CURRENT_TIMESTAMP,
  `del_flag` tinyint NOT NULL DEFAULT '0',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_gbsm_book_subject` (`book_id`,`local_subject_id`),
  KEY `idx_gbsm_standard` (`tenant_id`,`standard_id`),
  KEY `idx_gbsm_common` (`tenant_id`,`common_subject_id`)
) ENGINE=InnoDB AUTO_INCREMENT=32812 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='账簿×科目映射（多准则出多套核算数据的桥梁）';
/*!40101 SET character_set_client = @saved_cs_client */;

